mcp_gateway {
  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "UPDATE zt_bug SET status='resolved', resolution='fixed', resolvedBuild='trunk', resolvedBy='tiany', resolvedDate=NOW(), assignedTo='<openedBy>', lastEditedBy='tiany', lastEditedDate=NOW() WHERE id=6965;",
    "session_id": "<session_id>"
  }
}
核验: affected rows = 1

## 5) INSERT zt_action（14 列，files 挂附件 id 列表或 NULL）
