  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "UPDATE zt_file SET objectType='bug',objectID=6965,addedBy='tiany',addedDate=NOW() WHERE id IN (24372);",
